#!/usr/bin/env python3
"""Read selected endpoint bounds locally and check claims against their owner."""
import argparse,json,subprocess,time
from pathlib import Path
from replay import save
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--binary',type=Path,required=True);p.add_argument('--root',type=Path,required=True);p.add_argument('--model',type=Path,required=True);p.add_argument('--threads',type=int,default=8);args=p.parse_args();root=args.root.resolve();c=json.loads((root/'certificate.json').read_text());q=c['query']
# Scientific query choices are explicit. The model's job is to read four values.
prompt='Read the endpoint certificate supplied as context. Return exactly four equality claims: rational paths ["readings",1,"event_fraction_contrast_lower",0] and ["readings",1,"event_fraction_contrast_upper",0], rational path ["groups",0,"size"], and count path ["unidentified_event_count"]. Copy their actual values and the full source and certificate hashes. Use the native result indices retained in the reader; do not derive other quantities. The first three items MUST use value_type rational and JSON string values, including group size because that source member is encoded as a rational string. The fourth MUST use value_type count and a JSON integer value. Never change a requested type to integer. The compact facts member supplies the original root unidentified_event_count value.'
request=dict(schema='gadget.scientific.workflow.v1',id='local-interval-reader',source_digest=c['source_digest'],limits=dict(depth=2,nodes=4,model_calls=1,parallel_workers=args.threads),definitions=[],entry=dict(id='source-analysis-reader-check',type='sequence',steps=[dict(id='endpoint-analysis',type='query',query=q),dict(id='local-reader',type='model',role='reader',prompt=prompt,context=['endpoint-analysis']),dict(id='check',type='check_claims',**{'from':'endpoint-analysis'},claims_from='local-reader')]))
roles=dict(schema='gadget.local.roles.v1',models=[dict(role='reader',model=str(args.model.resolve()),task='claim_reader',threads=args.threads,context_tokens=16384,output_tokens=1536)])
save(root/'local-reader-request.json',request);save(root/'local-reader-roles.json',roles)
argv=[str(args.binary.resolve()),'workflow','--study',str(root/'study/study.json'),'--request',str(root/'local-reader-request.json'),'--models',str(root/'local-reader-roles.json')];start=time.perf_counter();r=subprocess.run(argv,text=True,capture_output=True);save(root/'local-reader.raw.json',r.stdout);save(root/'local-reader.stderr',r.stderr);elapsed=time.perf_counter()-start
if r.returncode:raise RuntimeError(r.stderr)
out=json.loads(r.stdout);checks=[e['result'] for e in out['trace'] if e['type']=='check_claims' and 'result' in e];assert out['status']=='complete' and len(checks)==1 and checks[0]['matched']==4 and checks[0]['contradicted']==0,out.get('error',checks);save(root/'local-reader.json',out);save(root/'local-reader-timing.json',dict(seconds=elapsed,returncode=r.returncode,model_name=args.model.name,task='Read four declared numerical claims, checked against their original native certificate',model_sha256=__import__('hashlib').sha256(args.model.read_bytes()).hexdigest()))
print(json.dumps(dict(status='PASS',seconds=elapsed)))
